for (int d = 0; d < num_d_vecs; d++) {
    float4 vk = vec_K[d];
    const scalar_t* sk = reinterpret_cast<const scalar_t*>(&vk);
    #pragma unroll
    for (int e = 0; e < VEC_ELEMS; e++) {
        dot += s_q[d * VEC_ELEMS + e] * static_cast<float>(sk[e]);
