}
```

This is a simple change that should work correctly and improve memory throughput.

Similarly for V in the weighted sum:

```cuda
// Current:
for (int d = tid; d < head_dim; d += bdim) {
    float acc = 0.0f;
    for (int j = 0; j < kv_len; j++) {
        int base_v = base_kv + j * head_dim;
        acc += scores[j] * static_cast<float>(__ldg(&V[base_v + d]));
    }
