for (int dv = tid; dv < num_d_vecs; dv += bdim) {
    float acc[VEC_ELEMS];
    #pragma unroll
    for (int e = 0; e < VEC_ELEMS; e++) acc[e] = 0.0f;
    for (int j = 0; j < kv_len; j++) {
