        float4 vv = reinterpret_cast<const float4*>(&V[base_v])[0];
        const scalar_t* sv = reinterpret_cast<const scalar_t*>(&vv);
        #pragma unroll
        for (int e = 0; e < VEC_ELEMS; e++) {
