display.text:
/*
 * Rotary Positional Embedding (RoPE) CUDA kernel — optimized implementation
 *
 * Optimizations over baseline:
 *   - Separate input/output buffers (eliminates x.clone(), halves memory traffic)
 *   - Shared-memory inv_freq via exp2f (replaces per-thread pow(); ~50x faster)
 *   - float sincosf via hardware SFU (replaces double sincos; ~5x faster)
 *   - log2_base precomputed on host and passed as kernel arg
 *   - __launch_bounds__ for better register allocation
 */

#include <torch/extension.h>
#include <cuda_runtime.h>
#include <cuda_fp16.h>
#include <math.h>

template <typename scalar_t>
__global__ __launch_bounds__(256)
void rotary_embedding_kernel(
    const scalar_t* __restrict__ input,
    scalar_t* __restrict__ output,
    const int* __restrict__ positions,
    int seq_len,
    int num_heads,
    int head_dim,
    float log2_base,
    int total_pairs
) {
    int idx = blockIdx.x * blockDim.x + threadIdx.x;
    if (idx >= total_pairs) return;

    int half_dim = head_dim / 2;

    extern __shared__ float s_inv_freq[];
    if (threadIdx.x < half_dim) {
        s_inv_freq[threadIdx.x] = exp2f(-2.0f * threadIdx.x / head_dim * log2_base);
    }
    __syncthreads();

    int pair_idx = idx % half_dim;
    int tmp = idx / half_dim;
    int head = tmp % num_heads;
    int tmp2 = tmp / num_heads;
    int seq = tmp2 % seq_len;
    int batch = tmp2 / seq_len;

    int m = positions[batch * seq_len + seq];
    float angle = static_cast<float>(m) * s_inv_freq[pair_idx];

    float sin_val, cos_val;
    sincosf(angle, &sin_val, &cos_val);

    int base_idx = ((batch * seq_len + seq) * num_heads + head) * head_dim;
    int i0 = base_idx + pair_idx;
    int i1 = base_idx + pair_idx + half_dim;

    float x0 = static_cast<float>(input[i0]);
    float x1 = static_cast<float>(input[i1]);

    output[i0] = static_cast<scalar_t>(x0 * cos_val - x1 * sin_val);
    output[i1] = static_cast<scalar_t>(x1 * cos_val + x0 * sin_val);
}

torch::Tensor agent_rotary_embedding(
    torch::Tensor x,
    torch::Tensor positions,
    double base
) {
    auto output = torch::empty_like(x);
    int batch = x.size(0);
    int seq_len = x.size(1);
    int num_heads = x.size(2);
    int head_dim = x.size(3);
    int half_dim = head_dim / 2;

    int total_pairs = batch * seq_len * num_heads * half_dim;
    int threads = 256;
    int blocks = (total_pairs + threads - 1) / threads;
    size_t smem_size = half_dim * sizeof(float);

    AT_DISPATCH_FLOATING_TYPES_AND2(
        at::ScalarType::Half, at::ScalarType::BFloat16,
        x.scalar_type(), "rotary_embedding", [&] {
            rotary_embedding_kernel<scalar_t><<<blocks, threads, smem_size>>>(
                x.data_ptr<scalar_t>(),
                output.data_ptr<scalar_t>(),
                positions.data_ptr<int>(),
                seq_len, num_heads, head_dim,
                log2f(static_cast<float>(base)),
                total_pairs
            );
        }
    );

    return output;
}

/*
 * RMSNorm CUDA kernel — optimized implementation
 *
 * Computes: output = (x / rms(x)) * weight
 * where rms(x) = sqrt(mean(x^2) + eps)
 *
 * Optimizations over baseline:
 *   - float4 vectorized loads/stores (8 half or 4 float per load)
 *   - Reduced thread count with more work per thread
 *   - __launch_bounds__ for better register allocation
 */

#include <torch/extension.h>
#include <cuda_runtime.h>
#include <cuda_fp16.h>
#include <math.h>

template <typename scalar_t>
__global__ __launch_bounds__(512)
void rmsnorm_kernel(
    const scalar_t* __restrict__ input,
    const scalar_t* __restrict__ weight,
    scalar_t* __restrict__ output,
    int hidden_size,
    float eps
) {
    int row = blockIdx.x;
    const scalar_t* x = input + row * hidden_size;
    scalar_t* o = output + row * hidden_size;

    constexpr int VEC_ELEMS = sizeof(float4) / sizeof(scalar_t);
    const int num_vecs = hidden_size / VEC_ELEMS;
    const int remainder_start = num_vecs * VEC_ELEMS;

    const float4* vec_x = reinterpret_cast<const float4*>(x);
    const float4* vec_w = reinterpret_cast<const float4*>(weight);
    float4* vec_o = reinterpret_cast<float4*>(o);

    float sum_sq = 0.0f;
    for (int i = threadIdx.x; i < num_vecs; i += blockDim.x) {
        float4 vx = vec_x[i];
        const scalar_t* sx = reinterpret_cast<const scalar_t*>(&vx);
        #pragma unroll
        for (int j = 0; j < VEC_ELEMS; j++) {
            float val = static_cast<float>(sx[j]);
            sum_sq += val * val;
        }
    }
    for (int i = remainder_start + threadIdx.x; i < hidden_size; i += blockDim.x) {
        float val = static_cast<float>(__ldg(&x[i]));
        sum_sq += val * val;
    }

    for (int offset = warpSize / 2; offset > 0; offset >>= 1)
        sum_sq += __shfl_down_sync(0xffffffff, sum_sq, offset);

    __shared__ float shared[32];
    int lane = threadIdx.x & 31;
    int warp_id = threadIdx.x >> 5;

    if (lane == 0) shared[warp_id] = sum_sq;
    __syncthreads();

    if (warp_id == 0) {
        int num_warps = (blockDim.x + 31) >> 5;
        sum_sq = (lane < num_warps) ? shared[lane] : 0.0f;
        for (int offset = warpSize / 2; offset > 0; offset >>= 1)
            sum_sq += __shfl_down_sync(0xffffffff, sum_sq, offset);
    }

    __shared__ float s_rms_inv;
    if (threadIdx.x == 0) {
        s_rms_inv = rsqrtf(sum_sq / hidden_size + eps);
    }
    __syncthreads();

    float rms_inv = s_rms_inv;

    for (int i = threadIdx.x; i < num_vecs; i += blockDim.x) {
        float4 vx = vec_x[i];
        float4 vw = vec_w[i];
        const scalar_t* sx = reinterpret_cast<const scalar_t*>(&vx);
        const scalar_t* sw = reinterpret_cast<const scalar_t*>(&vw);
        float4 vo;
        scalar_t* so = reinterpret_cast<scalar_t*>(&vo);
        #pragma unroll
        for (int j = 0; j < VEC_ELEMS; j++) {
            so[j] = static_cast<scalar_t>(static_cast<float>(sx[j]) * rms_inv * static_cast<float>(sw[j]));
        }
        vec_o[i] = vo;
    }
    for (int i = remainder_start + threadIdx.x; i < hidden_size; i += blockDim.x) {
        float val = static_cast<float>(__ldg(&x[i]));
        float w = static_cast<float>(__ldg(&weight[i]));
        o[i] = static_cast<scalar_t>(val * rms_inv * w);
    }
}

torch::Tensor agent_rmsnorm(torch::Tensor input, torch::Tensor weight, double eps) {
    auto output = torch::empty_like(input);
    int batch = input.size(0);
    int hidden = input.size(1);

    dim3 grid(batch);

    AT_DISPATCH_FLOATING_TYPES_AND2(
        at::ScalarType::Half, at::ScalarType::BFloat16,
        input.scalar_type(), "rmsnorm", [&] {
            constexpr int VEC_ELEMS = sizeof(float4) / sizeof(scalar_t);
            int num_vecs = hidden / VEC_ELEMS;
            dim3 block(min(max(num_vecs, 64), 512));

            rmsnorm_kernel<scalar_t><<<grid, block>>>(
                input.data_ptr<scalar_t>(),
                weight.data_ptr<scalar_t>(),
                output.data_ptr<scalar_t>(),
                hidden, static_cast<float>(eps)
            );
        }
    );

    return output;
}

/*
 * Fused SwiGLU MLP CUDA kernel — optimized implementation
 *
 * Uses cuBLAS (via torch::matmul) for the heavy GEMM work,
 * then fuses the SiLU activation + elementwise multiply in-place.
 *
 * Optimizations over baseline:
 *   - float4 vectorized loads/stores (8 half or 4 float per load)
 *   - Process vec_elems * UNROLL elements per thread
 *   - __launch_bounds__ for better register allocation
 */

#include <torch/extension.h>
#include <cuda_runtime.h>
#include <cuda_fp16.h>
#include <math.h>

template <typename scalar_t>
__global__ __launch_bounds__(256)
void fused_silu_mul_inplace_kernel(
    scalar_t* __restrict__ gate,
    const scalar_t* __restrict__ up,
    int N
) {
    constexpr int VEC_ELEMS = sizeof(float4) / sizeof(scalar_t);
    const int num_vecs = N / VEC_ELEMS;
    const int remainder_start = num_vecs * VEC_ELEMS;

    float4* vec_gate = reinterpret_cast<float4*>(gate);
    const float4* vec_up = reinterpret_cast<const float4*>(up);

    int idx = blockIdx.x * blockDim.x + threadIdx.x;

    if (idx < num_vecs) {
        float4 vg = vec_gate[idx];
        float4 vu = vec_up[idx];
        scalar_t* sg = reinterpret_cast<scalar_t*>(&vg);
        const scalar_t* su = reinterpret_cast<const scalar_t*>(&vu);
        float4 vo;
        scalar_t* so = reinterpret_cast<scalar_t*>(&vo);
        #pragma unroll
        for (int j = 0; j < VEC_ELEMS; j++) {
            float g = static_cast<float>(sg[j]);
            float u = static_cast<float>(su[j]);
            float silu_g = g / (1.0f + expf(-g));
            so[j] = static_cast<scalar_t>(silu_g * u);
        }
        vec_gate[idx] = vo;
    }

    int rem_idx = remainder_start + idx;
    if (rem_idx < N) {
        float g = static_cast<float>(gate[rem_idx]);
        float u = static_cast<float>(up[rem_idx]);
        float silu_g = g / (1.0f + expf(-g));
        gate[rem_idx] = static_cast<scalar_t>(silu_g * u);
    }
}

torch::Tensor agent_fused_mlp(
    torch::Tensor input,
    torch::Tensor gate_weight,
    torch::Tensor up_weight
) {
    auto gate_proj = torch::mm(input, gate_weight.t());
    auto up_proj = torch::mm(input, up_weight.t());

    int N = gate_proj.numel();

    AT_DISPATCH_FLOATING_TYPES_AND2(
        at::ScalarType::Half, at::ScalarType::BFloat16,
        input.scalar_type(), "fused_mlp", [&] {
            constexpr int VEC_ELEMS = sizeof(float4) / sizeof(scalar_t);
            int num_vecs = N / VEC_ELEMS;
            int threads = 256;
            int blocks = (num_vecs + threads - 1) / threads;
            if (blocks == 0) blocks = 1;

            fused_silu_mul_inplace_kernel<scalar_t><<<blocks, threads>>>(
                gate_proj.data_ptr<scalar_t>(),
                up_proj.data_ptr<scalar_t>(),
                N
            );
        }
    );

    return gate_proj;
}

